-- Audio, music & voice, Expert tier (days 61-80). Authored content, UNPUBLISHED until a person reviews it in Admin.
insert into public.day
  (track_id, tier_id, day_number, title, objective, lesson_md, skill_focus, assignment_md, rubric,
   est_minutes, is_published, credit_budget, submission_type, ai_evaluate, requires_review)
select t.id, ti.id, v.n, v.title, v.objective, v.lesson_md, v.skill_focus, v.assignment_md, v.rubric,
       v.est_minutes, false, null, v.submission_type, v.ai_evaluate, v.requires_review
from public.track t
join public.tier ti on ti.track_id = t.id and ti.slug = 'expert'
cross join (values
  (61, $t61a$Sonic identity strategy$t61a$, $t61b$Define how a brand should sound.$t61b$, $t61c$A sonic identity covers voice, music style, sound logo, UI sounds and rules for use. Start from brand values and audience, then test options with listeners.$t61c$, $t61d$Sonic identity strategy$t61d$, $t61e$Write a sonic identity strategy with values, sound principles and three test options.$t61e$, $t61f$[{"criterion": "Principles clear", "max_points": 40, "guidance": "Specific."}, {"criterion": "Tied to brand", "max_points": 30, "guidance": "Reasoned."}, {"criterion": "Tested", "max_points": 30, "guidance": "Listeners."}]$t61f$::jsonb, 60, 'text', false, false),
  (62, $t62a$Advanced sound design and synthesis$t62a$, $t62b$Create original sounds.$t62b$, $t62c$Layer synthesis, sampling and processing. Document patches so sounds are reproducible and cleared.$t62c$, $t62d$Advanced sound design and synthesis$t62d$, $t62e$Create a set of six branded sounds with documentation.

**Sharing audio:** upload (unlisted) and paste the link. Audio is checked by a person.$t62e$, $t62f$[{"criterion": "Distinct set", "max_points": 40, "guidance": "Cohesive."}, {"criterion": "Documented", "max_points": 30, "guidance": "Reproducible."}, {"criterion": "Clean", "max_points": 30, "guidance": "Quality."}]$t62f$::jsonb, 90, 'link', false, false),
  (63, $t63a$Immersive and spatial audio$t63a$, $t63b$Design for space.$t63b$, $t63c$Binaural and multichannel mixes place sound in space. Check compatibility and fall back to stereo gracefully.$t63c$, $t63d$Immersive and spatial audio$t63d$, $t63e$Create a 30-second spatial scene with stereo fallback.

**Sharing audio:** upload (unlisted) and paste the link. Audio is checked by a person.$t63e$, $t63f$[{"criterion": "Space convincing", "max_points": 40, "guidance": "Placed."}, {"criterion": "Fallback", "max_points": 30, "guidance": "Works."}, {"criterion": "Notes", "max_points": 30, "guidance": "Documented."}]$t63f$::jsonb, 90, 'link', false, false),
  (64, $t64a$Mixing and mastering to spec$t64a$, $t64b$Meet professional standards.$t64b$, $t64c$Reference tracks, loudness targets, true peak, dynamic range and translation checks on many speakers.$t64c$, $t64d$Mixing and mastering to spec$t64d$, $t64e$Mix and master a track and provide a translation check report.

**Sharing audio:** upload (unlisted) and paste the link. Audio is checked by a person.$t64e$, $t64f$[{"criterion": "Clear mix", "max_points": 40, "guidance": "Balanced."}, {"criterion": "Specs met", "max_points": 30, "guidance": "Values."}, {"criterion": "Translation checked", "max_points": 30, "guidance": "Report."}]$t64f$::jsonb, 90, 'link', false, false),
  (65, $t65a$Expert project 1: a sonic identity system$t65a$, $t65b$Deliver strategy plus assets.$t65b$, $t65c$Show Module 1. Deliver a **sonic identity system**: strategy, sound logo, six UI sounds and a mastered anthem.

A person reviews your work and can ask for revisions.$t65c$, $t65d$Expert project 1: a sonic identity system$t65d$, $t65e$Submit all assets and documents.

**Sharing audio:** upload (unlisted) and paste the link. Audio is checked by a person.$t65e$, $t65f$[{"criterion": "Strategy and coherence", "max_points": 30, "guidance": "One identity."}, {"criterion": "Sound quality", "max_points": 30, "guidance": "Professional."}, {"criterion": "Documentation", "max_points": 20, "guidance": "Complete."}, {"criterion": "Rights", "max_points": 20, "guidance": "Clean."}]$t65f$::jsonb, 240, 'link', false, true),
  (66, $t66a$Composition and arrangement with AI$t66a$, $t66b$Use AI as a collaborator.$t66b$, $t66c$Sketch ideas with AI, then arrange, edit and perform or replace parts yourself. Know the terms on commercial use and originality checks.$t66c$, $t66d$Composition and arrangement with AI$t66d$, $t66e$Create a two-minute piece using AI sketches and your own edits; document what is yours.

**Sharing audio:** upload (unlisted) and paste the link. Audio is checked by a person.$t66e$, $t66f$[{"criterion": "Musical shape", "max_points": 35, "guidance": "Structured."}, {"criterion": "Human contribution", "max_points": 35, "guidance": "Clear."}, {"criterion": "Terms checked", "max_points": 30, "guidance": "Documented."}]$t66f$::jsonb, 120, 'link', false, false),
  (67, $t67a$Dialogue, ADR and voice direction at scale$t67a$, $t67b$Produce many voice lines.$t67b$, $t67c$Batch scripts, direction notes, consistent settings, naming and QC. Only use consented or licensed voices.$t67c$, $t67d$Dialogue, ADR and voice direction at scale$t67d$, $t67e$Produce 20 lines in a consistent voice with a QC log.

